async function addSeed(
  client: AlchemystAI,
  seed: Seed,
  runId: string,
): Promise<void> {
  const fileName = `${seed.key}-${runId}.md`;
  try {
    // Per the official Alchemyst docs the storage-side metadata key is
    // `group_name` (snake_case) and `file_name`. The TypeScript SDK's
    // `ContextAddParams.Metadata` type only declares the camelCase fields,
