    await (client.v1.context.add as any)({
      context_type: 'resource',
      scope: 'internal',
      source: 'context-arithmetic-demo',
      documents: [
        {
          content: seed.content,
          // Per-document metadata matching the documented storage form.
          metadata: {
            file_name: fileName,
            group_name: seed.groups,
          },
        },
      ],
      // Top-level metadata is also populated with the camelCase form the
      // SDK type declares, plus the snake_case `group_name`. The backend
      // is documented to treat them as the same field, so this gives the
      // widest compatibility.
