        fileName: fileName,
        fileType: 'text/markdown',
        group_name: seed.groups,
      },
    });
    process.stderr.write(`[info] ingested ${seed.key}\n`);
  } catch (e) {
    if (e instanceof APIError && e.status === 409) {
      process.stderr.write(
        `[info] ${seed.key} already present (file_name=${fileName}); reusing\n`,
      );
      return;
    }
    const status = (e as any)?.status;
    const message = (e as Error)?.message ?? String(e);
    process.stderr.write(`[warn] failed to ingest ${seed.key} (status=${status}): ${message}\n`);
  }
}

